import type { AgentSpec } from 'claude-code'

import { FLAG_NAMES, type Pin } from './flags'

// The three codex agent types: what each pins, how it is shown, and how it
// is offered to the model.

export const TYPES: Record<string, { pin?: Pin; shown: string }> = {
  'codex:read': { pin: { sandbox: 'read-only' }, shown: 'Codex read-only' },
  'codex:write': { pin: { sandbox: 'workspace-write' }, shown: 'Codex workspace-write' },
  'codex:run': { shown: 'Codex' },
}

// The agent's system prompt, which no model reads while the mod answers its
// turns. The agent list still summarises a running agent from it, so it opens
// with what the agent does; a stand-in model, reached only if the turn.step
// hook fails, reports that instead of answering.
const FALLBACK = `This agent passes its task to OpenAI Codex, which does the work in its place: the codex mod runs Codex and reports Codex's answer. A model reading this means the mod did not run, so do nothing else and give as your final report that Codex did not run and that this agent's transcript and the debug log say why.`

const CHOOSING = (models: string[]) =>
  ` Codex CLI flags may open the prompt, one per line as \`codex exec --help\` names them without dashes (\`model: <id>\`, \`effort: <level>\`` +
  (models.length > 0 ? `; models: ${models.join(', ')}` : '') +
  `); left out, Codex uses its own config. When Codex asks for an approval or an answer, the agent reports the question; send it the reply as a message.`

// The agent types as `$.agent.register` takes them, offering these models.
export function specsOf(models: string[]): AgentSpec[] {
  const common = { prompt: FALLBACK, tools: ['Read'], model: 'haiku', omitClaudeMd: true } as const
  const choosing = CHOOSING(models)
  return [
    {
      ...common,
      name: 'read',
      description:
        'OpenAI Codex in a read-only sandbox: a second opinion, review, research or scoping by a different model. Give it a self-contained prompt; it cannot see this conversation.' + choosing,
    },
    {
      ...common,
      name: 'write',
      description:
        'OpenAI Codex with workspace-write in the working directory: bounded implementation by a different model. Give it a self-contained prompt naming the files it owns; it cannot see this conversation.' + choosing,
    },
    {
      ...common,
      name: 'run',
      description:
        `OpenAI Codex as your Codex config sets it up (sandbox, approvals, reviewer), changed per call by any of its flags: ${FLAG_NAMES.join(', ')}. Give it a self-contained prompt; it cannot see this conversation.` + choosing,
    },
  ]
}

files.hooks/band.tsx:
import type { RenderElement } from 'claude-code'

// The band above the prompt in a codex agent's view: the reply to the last
// /codex- command run there, over whatever the band holds beneath.
export function replyBand(ui: { Box: any; Text: any }, reply: string, below: RenderElement | null) {
  const { Box, Text } = ui
  return (
    <Box flexDirection="column">
      <Text>{reply}</Text>
      {below}
    </Box>
  )
}

files.hooks/commands.ts:
import type { CodexOptionName, CodexRun } from '../types'
import { APPROVALS, flagsOf, SANDBOXES, type Pin } from './flags'

// `/codex-*` messages, which a codex agent answers itself and never passes to
// Codex: settings for its next Codex turns, its status, and help. They are
// typed in the agent's view, where Claude Code hands a command it does not
// know to the agent as a message. A setting is the Codex option line it
// names, so it is checked by the option rules and the agent type's pin.

export type Options = Partial<Record<CodexOptionName, string>>

// The reply, and the agent's settings when the command changed them.
export type Answer = { reply: string; options?: Options }

const SETTINGS: Record<string, { option: CodexOptionName; value: string; what: string }> = {
  model: { option: 'model', value: '<id>', what: 'The Codex model' },
  effort: { option: 'effort', value: '<level>', what: 'The reasoning effort' },
  sandbox: { option: 'sandbox', value: `<${SANDBOXES.join('|')}>`, what: 'The sandbox' },
  approvals: { option: 'ask-for-approval', value: `<${APPROVALS.join('|')}>`, what: 'When Codex asks for approval' },
}

// The commands as Claude Code registers them, listed in a codex agent's view.
export const SPECS: { name: string; description: string; argumentHint?: string; immediate: true }[] = [
  ...Object.entries(SETTINGS).map(([name, { value, what }]) => ({
    name: `codex-${name}`,
    description: `${what} for this codex agent, from its next Codex turn`,
    argumentHint: value,
    immediate: true as const,
  })),
  { name: 'codex-status', description: 'What Codex runs this agent with, its session and its tokens', immediate: true },
  { name: 'codex-help', description: 'The codex agent commands', immediate: true },
]

const NAMES = SPECS.map(spec => `/${spec.name}`)

const HELP = [
  'Codex commands for this agent (a setting applies from its next Codex turn):',
  ...Object.entries(SETTINGS).map(([name, { value }]) => `  /codex-${name} ${value}`),
  '  /codex-status   what Codex runs with, the session and its tokens',
  '  /codex-help     this list',
].join('\n')

// The footer hint while a codex agent's view is open.
export const HINT = NAMES.join(' ')

const COMMAND = /^\/codex-(\S*)(?:\s+([\s\S]*))?$/

export function isCommand(text: string): boolean {
  return text.trimStart().startsWith('/codex-')
}

export function answerOf(text: string, options: Options, pin: Pin | undefined, run: CodexRun | undefined): Answer {
  const match = COMMAND.exec(text.trim())
  const name = match?.[1] ?? ''
  const value = (match?.[2] ?? '').trim()
  if (name === 'status') return { reply: statusOf(options, run) }
  const setting = SETTINGS[name]
  if (!setting || value === '') {
    const why = name === 'help' ? '' : setting ? `codex: /codex-${name} needs a value.\n\n` : `codex: no /codex-${name}.\n\n`
    return { reply: `${why}${HELP}` }
  }
  // One plain word: a value that spans lines would carry option lines of its own.
  if (/\s/.test(value)) return { reply: `codex: /codex-${name} takes one plain value, not "${value}".` }
  const parsed = flagsOf(`${setting.option}: ${value}`, pin)
  if ('error' in parsed) return { reply: `codex: ${parsed.error}` }
  if (parsed.prompt !== '') return { reply: `codex: /codex-${name} takes one plain value, not "${value}".` }
  return { reply: `codex: ${name} ${value} from the next Codex turn.`, options: { ...options, [setting.option]: value } }
}

// Commands answered in order, each seeing the settings the ones before it
// left; the replies, and the agent's settings after them.
export function answersOf(texts: readonly string[], options: Options, pin: Pin | undefined, run: CodexRun | undefined): { replies: string[]; options: Options } {
  let mine = options
  const replies = texts.map(text => {
    const answer = answerOf(text, mine, pin, run)
    mine = answer.options ?? mine
    return answer.reply
  })
  return { replies, options: mine }
}

// The settings as thread/start and thread/resume take them: a resumed
// session keeps the model, sandbox and approvals it ran with unless the call
// names others, so they go with every call.
export function threadParamsOf(options: Options): { model?: string; sandbox?: string; approvalPolicy?: string; config?: Record<string, string> } {
  return {
    ...(options.model ? { model: options.model } : {}),
    ...(options.sandbox ? { sandbox: options.sandbox } : {}),
    ...(options['ask-for-approval'] ? { approvalPolicy: options['ask-for-approval'] } : {}),
    ...(options.effort ? { config: { model_reasoning_effort: options.effort } } : {}),
  }
}

const count = (n: number) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

function statusOf(options: Options, run: CodexRun | undefined): string {
  const now: Record<CodexOptionName, string | undefined> = {
    model: run?.model,
    effort: run ? (run.effort ?? 'default') : undefined,
    sandbox: run?.sandbox,
    'ask-for-approval': run?.approvals,
  }
  const rows = Object.entries(SETTINGS).flatMap(([name, { option }]) => {
    const next = options[option]
    if (next !== undefined && next !== now[option]) return [`${name.padEnd(10)}${next} from the next Codex turn${now[option] ? ` (now ${now[option]})` : ''}`]
    return now[option] ? [`${name.padEnd(10)}${now[option]}`] : []
  })
  if (!run) return ['codex: no Codex turn yet.', ...rows].join('\n')
  const { input, cached, output } = run.tokens
  return [...rows, `${'session'.padEnd(10)}${run.threadId}`, `${'tokens'.padEnd(10)}${count(input)} in (${count(cached)} cached), ${count(output)} out, running total`].join('\n')
}

files.hooks/flags.ts:
// A codex agent's prompt may open with Codex CLI flags, one per line, spelled
// as `codex exec --help` spells them without the dashes: `model: gpt-6-astra`,
// `sandbox: workspace-write`, `approve-for-me`, `config: key=value`. They
// choose how Codex runs and are not part of the task. Codex's own config fills
// in everything not chosen.

export type Flags = {
  // Arguments for `codex app-server`: config overrides and feature switches.
  args: string[]
  model?: string
  effort?: string
  cwd?: string
  ephemeral?: boolean
  images: string[]
  outputSchema?: string
  addDirs: string[]
  prompt: string
}

export type Parsed = Flags | { error: string }

// What the read and write types pin: a flag that changes it is refused there.
export type Pin = { sandbox: string }

const WORD = /^[A-Za-z0-9._/:@+-]+$/
const CONFIG = /^[A-Za-z0-9_.-]+=.+$/
const PINNED = /^(sandbox_mode|approval_policy|approvals_reviewer|sandbox_workspace_write)\b/

export const SANDBOXES = ['read-only', 'workspace-write', 'danger-full-access']
export const APPROVALS = ['untrusted', 'on-request', 'never']

// `codex exec` flags that have no meaning for a session the mod drives.
const EXEC_ONLY: Record<string, string> = {
  profile: 'codex app-server takes no --profile; set the values with config: lines',
  json: 'the mod already reads Codex events',
  'output-last-message': 'the report goes back to Claude',
  color: 'there is no terminal',
  'skip-git-repo-check': 'the mod never needs a git repo',
  worktree: 'codex app-server takes no --worktree',
  'ignore-user-config': 'codex app-server takes no --ignore-user-config',
  'ignore-rules': 'codex app-server takes no --ignore-rules',
  'dangerously-bypass-hook-trust': 'codex app-server takes no --dangerously-bypass-hook-trust',
  oss: 'name the provider with local-provider: lmstudio or ollama',
}

const ALIASES: Record<string, string> = {
  m: 'model',
  s: 'sandbox',
  a: 'ask-for-approval',
  approval: 'ask-for-approval',
  c: 'config',
  C: 'cd',
  i: 'image',
  auto: 'approve-for-me',
  'reasoning-effort': 'effort',
}

// `--sandbox read-only`, `-s=read-only`, `sandbox: read-only`, or a flag that
// takes no value alone on its line (`approve-for-me`). "search the code" has
// neither the dashes nor the colon; see isOptionLine for prose that has one.
const DASHED = /^--?([A-Za-z][A-Za-z-]*)(?:[ =]\s*(.*))?$/
const PLAIN = /^([A-Za-z][A-Za-z-]*)(?::\s*(.*))?$/

type Apply = (flags: Flags, value: string) => string | undefined

function quoted(key: string, value: string, flags: Flags): string | undefined {
  if (!WORD.test(value)) return `${key} needs a plain value, not "${value}"`
  flags.args.push('-c', `${key}="${value}"`)
}

function oneOf(key: string, allowed: string[]): Apply {
  return (flags, value) => (allowed.includes(value) ? quoted(key, value, flags) : `${key} is one of ${allowed.join(', ')}`)
}

// `path`: the value is a path, which may hold spaces when it starts like one.
const FLAGS: Record<string, { apply: Apply; pinned?: true; bare?: true; path?: true }> = {
  model: { apply: (f, v) => quoted('model', v, f) ?? void (f.model = v) },
  effort: { apply: (f, v) => quoted('model_reasoning_effort', v, f) ?? void (f.effort = v) },
  sandbox: { apply: oneOf('sandbox_mode', SANDBOXES), pinned: true },
  'ask-for-approval': { apply: oneOf('approval_policy', APPROVALS), pinned: true },
  // As `codex exec --approve-for-me`: Codex's automatic reviewer decides, in
  // the workspace-write sandbox.
  'approve-for-me': {
    apply: f => void f.args.push('-c', 'approvals_reviewer="auto_review"', '-c', 'sandbox_mode="workspace-write"'),
    pinned: true,
    bare: true,
  },
  'dangerously-bypass-approvals-and-sandbox': {
    apply: f => void f.args.push('-c', 'sandbox_mode="danger-full-access"', '-c', 'approval_policy="never"'),
    pinned: true,
    bare: true,
  },
  'add-dir': { apply: (f, v) => void f.addDirs.push(v), pinned: true, path: true },
  search: { apply: f => void f.args.push('-c', 'web_search="live"'), bare: true },
  'local-provider': { apply: (f, v) => quoted('model_provider', v, f) },
  config: {
    apply: (f, v) => (CONFIG.test(v) ? void f.args.push('-c', v) : `config takes key=value, not "${v}"`),
  },
  enable: { apply: (f, v) => (WORD.test(v) ? void f.args.push('--enable', v) : `enable takes a feature name`) },
  disable: { apply: (f, v) => (WORD.test(v) ? void f.args.push('--disable', v) : `disable takes a feature name`) },
  'strict-config': { apply: f => void f.args.push('--strict-config'), bare: true },
  ephemeral: { apply: f => void (f.ephemeral = true), bare: true },
  // Pinned like add-dir: moving the folder moves the writable root.
  cd: { apply: (f, v) => void (f.cwd = v), pinned: true, path: true },
  image: { apply: (f, v) => void f.images.push(v), path: true },
  'output-schema': { apply: (f, v) => void (f.outputSchema = v), path: true },
}

export const FLAG_NAMES = Object.keys(FLAGS)

// Whether a line is shaped as an option line for this flag: a bare flag
// alone (or `true`), a config `key=value`, a path, or one plain value. A line
// of prose that only starts with a flag's name ("search: every call") is not,
// and is the task's.
function isOptionLine(name: string, value: string): boolean {
  const flag = FLAGS[name]
  if (flag?.bare) return value === '' || /^(true|yes|on)$/i.test(value)
  if (name === 'config') return CONFIG.test(value)
  if (flag?.path && /^[/~.]/.test(value)) return true
  return value !== '' && !/\s/.test(value)
}

// `Model:` and `Effort:` read in any case, as 0.2.5 read them; every other
// name as `codex exec --help` spells it, since `-C` and `-c` differ.
function nameOf(raw: string): string {
  const lower = raw.toLowerCase()
  if (lower === 'model' || lower === 'effort') return lower
  return ALIASES[raw] ?? raw
}

// Reads the leading option lines of a prompt. The first line that is not one
// ends them, and it and the rest are the task. An option line used wrongly,
// or one a pinned type refuses, is an error for the caller rather than a
// silent change of what Codex runs with.
export function flagsOf(text: string, pin?: Pin): Parsed {
  const flags: Flags = { args: [], images: [], addDirs: [], prompt: text }
  if (pin) flags.args.push('-c', `sandbox_mode="${pin.sandbox}"`, '-c', 'approval_policy="never"')
  const lines = text.split('\n')
  let used = 0
  for (const line of lines) {
    const match = DASHED.exec(line.trim()) ?? PLAIN.exec(line.trim())
    if (!match) break
    const name = nameOf(match[1]!)
    const value = (match[2] ?? '').trim()
    if (!(name in FLAGS || name in EXEC_ONLY) || !isOptionLine(name, value)) break
    if (name in EXEC_ONLY) return { error: `${name}: ${EXEC_ONLY[name]}` }
    const flag = FLAGS[name]!
    if (pin && (flag.pinned || (name === 'config' && PINNED.test(value)))) {
      return { error: `${name}: this agent type pins the ${pin.sandbox} sandbox; use codex:run to choose` }
    }
    const error = flag.apply(flags, value)
    if (error) return { error }
    used++
  }
  flags.prompt = lines.slice(used).join('\n').trim()
  return flags
}

files.hooks/model.ts:
import { nameOf } from './names'

// What Codex runs with: its config.toml's top-level model and reasoning
// effort, under what a codex agent's prompt chose.

export type Choice = { model?: string; effort?: string }

export function configOf(toml: string): Choice {
  const choice: Choice = {}
  for (const line of toml.split('\n')) {
    const text = line.trim()
    if (text.startsWith('[')) break
    const pair = /^([A-Za-z_]+)\s*=\s*["']([^"']+)["']/.exec(text)
    if (pair?.[1] === 'model') choice.model = pair[2]
    if (pair?.[1] === 'model_reasoning_effort') choice.effort = pair[2]
  }
  return choice
}

// `Sol 6.1 (high)`: the chosen model and effort over the config's. With
// neither naming a model, Codex picks its own; which one is known only once
// Codex runs (each turn's header names it), so the label says so.
export function labelOf(config: Choice, options: Choice): string {
  const id = options.model ?? config.model
  const model = id ? nameOf(id) : 'Codex default'
  const effort = options.effort ?? config.effort
  return effort ? `${model} (${effort})` : model
}

// The model ids Codex's model cache lists, newest first as it keeps them;
// empty when the cache is missing or its shape is not the one read here.
export function modelsOf(json: string): string[] {
  try {
    const cache = JSON.parse(json)
    const list = Array.isArray(cache) ? cache : (cache?.models ?? cache?.data)
    if (!Array.isArray(list)) return []
    return list.map((m: any) => m?.slug ?? m?.id).filter((s: unknown): s is string => typeof s === 'string')
  } catch {
    return []
  }
}

// What reading Codex's own files needs of the engine: the environment
// variables that place them, and a file read.
export type Files = {
  env: { CODEX_HOME?: string; HOME?: string; USERPROFILE?: string }
  read: (path: string) => Promise<string>
}

async function readOr(files: Files, name: string): Promise<string> {
  const { CODEX_HOME, HOME, USERPROFILE } = files.env
  try {
    return await files.read(`${CODEX_HOME ?? `${HOME ?? USERPROFILE}/.codex`}/${name}`)
  } catch {
    return ''
  }
}

// The model and effort Codex's config.toml names; empty when it names none.
export async function codexConfig(files: Files): Promise<Choice> {
  return configOf(await readOr(files, 'config.toml'))
}

// The model ids Codex's model cache lists.
export async function codexModels(files: Files): Promise<string[]> {
  return modelsOf(await readOr(files, 'models_cache.json'))
}

files.hooks/step.ts:
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Hook, TurnStepChunk, TurnUsage } from 'claude-code'

import type { CodexRun } from '../types'
import { TYPES } from './agents'
import { answersOf, isCommand, threadParamsOf } from './commands'
import { answerOf, apply, reportOf, STOPPED, type Run } from './events'
import { flagsOf, type Flags, type Pin } from './flags'
import { labelOf } from './model'
import { expiredAnswer, questionOf, replyOf, type Asked } from './questions'
import { HANDBACK, handsBack, lastAnswer, requestOf, rowsOf, undeliveredReport } from './request'
import { NO_CODEX, open, type Server } from './server'
import { openView, setReply } from './view'

// One step of a codex agent's loop: its model request answered by driving
// `codex app-server`, Codex's steps streamed as the agent's text, and Codex's
// answer or question handed back.

// A Codex turn paused on a question, by agent id: the server stays up until
// the agent's next message answers it.
const held = new Map<string, { server: Server; asked: Asked; threadId: string }>()

// The Codex turn each codex agent is running now, by agent id, so a message
// sent to the agent meanwhile can join it rather than wait for it to end.
const working = new Map<string, { server: Server; threadId: string; turnId: string }>()

// Adds a message to the agent's running Codex turn; false when no turn runs
// or Codex refused (the turn had just ended), so the message takes the usual
// way: the agent's next turn.
export async function steer(agentId: string, text: string): Promise<boolean> {
  const turn = working.get(agentId)
  if (!turn) return false
  try {
    await turn.server.call('turn/steer', { threadId: turn.threadId, expectedTurnId: turn.turnId, input: [{ type: 'text', text }] })
    return true
  } catch {
    return false
  }
}

// Ends every Codex turn left waiting on a question.
export function closeHeld(): void {
  for (const { server } of held.values()) server.close()
  held.clear()
}

// What each codex agent has passed to Codex, so a message is sent once; the
// prompt it was spawned with (register.ts records it); what its commands
// set; and what Codex last reported running it with.
const sent = atom({ plugin: 'codex', key: 'sent' } as const, {})
const openings = atom({ plugin: 'codex', key: 'openings' } as const, {})
const options = atom({ plugin: 'codex', key: 'options' } as const, {})
const runs = atom({ plugin: 'codex', key: 'runs' } as const, {})

// Records what Codex reported the agent's session runs with (or keeps the
// last), with its token total once Codex has counted it.
async function record($: EngineInterface, agentId: string, report: Omit<CodexRun, 'tokens'> | undefined, tokens?: CodexRun['tokens']): Promise<void> {
  await update($, runs, all => {
    const base = report ?? all[agentId]
    return base ? { ...all, [agentId]: { ...base, tokens: tokens ?? all[agentId]?.tokens ?? { input: 0, cached: 0, output: 0 } } } : all
  })
}

const shown = (text: string): TurnStepChunk => ({ kind: 'text', index: 0, text })

// Codex's progress also as notices in the agent's conversation, appended as
// it happens: a notice is what refreshes the agent list's activity line, while
// the agent's view shows the step's text. The model never reads a notice, and
// only the detailed transcript (ctrl+o) shows both. Display only, so a refused
// append changes nothing else.
async function note($: EngineInterface, agentId: string, text: string): Promise<void> {
  await $.session
    .append({ agentId, message: { type: 'system', content: [{ type: 'text', text: text.trimEnd() }] } })
    .catch(() => undefined)
}

// Resolves undefined when the step is aborted first; the listener goes once
// the wait settles, so a long turn does not pile them up on the signal.
export function unlessAborted<T>(signal: AbortSignal, promise: Promise<T>): Promise<T | undefined> {
  if (signal.aborted) return Promise.resolve(undefined)
  let stop = () => {}
  const aborted = new Promise<undefined>(resolve => {
    stop = () => resolve(undefined)
    signal.addEventListener('abort', stop, { once: true })
  })
  return Promise.race([promise, aborted]).finally(() => signal.removeEventListener('abort', stop))
}

const EXPIRED =
  'codex: the question Codex asked has expired: the Codex turn that asked it is gone (Codex exited, the session was resumed, or the mod reloaded), so nothing was answered. Send the task again to start a new turn.'

// The agent's `/codex-*` commands, answered in order; a setting is kept for
// its next Codex turn.
async function answered($: EngineInterface, agentId: string, commands: string[], pin?: Pin): Promise<string[]> {
  const last = (await read($, runs))[agentId]
  let replies: string[] = []
  await update($, options, all => {
    const answers = answersOf(commands, all[agentId] ?? {}, pin, last)
    replies = answers.replies
    return { ...all, [agentId]: answers.options }
  })
  return replies
}

// A registered /codex- command acts on the agent whose view is open and
// answers in that view's band; the main conversation is not sent the reply.
export const command: Hook<'command.run'> = async ($, e, next) => {
  if (!isCommand(`/${e.command}`)) return next(e)
  const id = openView()
  const agent = id === undefined ? undefined : (await $.agent.list()).find(a => a.id === id)
  const type = agent && TYPES[agent.type]
  if (!agent || !type) return { text: `Open a codex agent's view to use /${e.command}.` }
  const [reply] = await answered($, agent.id, [`/${e.command} ${e.args}`.trim()], type.pin)
  setReply(agent.id, reply!)
  $.ui.invalidate('ui.render')
  return {}
}

export const step: Hook<'turn.step'> = async function* ($, e, next) {
  const agentId = e.agentId
  if (!agentId) return yield* next(e)
  const agent = (await $.agent.list()).find(a => a.id === agentId)
  const type = agent && TYPES[agent.type]
  if (!type) return yield* next(e)

  const api = await $.session.messages({ as: 'api', agentId })
  if ('deny' in api) throw new Error(api.deny)
  const rows = rowsOf(api)
  const given = (await read($, sent))[agentId] ?? []
  const request = requestOf(rows, given, (await read($, openings))[agentId])
  // Codex's progress is the transcript's text; the report goes back with a
  // handback call, or as the final text where the loop has no such tool.
  const handback = handsBack(rows)

  const run: Run = {}
  let progress = ''
  let question: string | undefined
  let model = 'codex'
  let server: Server | undefined
  const show = (text: string) => {
    progress += text
    return shown(text)
  }
  // A `/codex-*` message is the mod's to answer; the rest is Codex's.
  const asked = request?.texts.filter(text => !isCommand(text)) ?? []
  const replies = request ? await answered($, agentId, request.texts.filter(isCommand), type.pin) : []
  for (const reply of replies) {
    yield show(`${reply}\n\n`)
    await note($, agentId, reply)
  }
  let report: Omit<CodexRun, 'tokens'> | undefined
  // Whether Codex took this step's messages: it started their turn, or its
  // question was answered. From then they are passed on, finished or not.
  let isTaken = false
  if (request) {
    const prompt = asked.join('\n\n')
    const pending = held.get(agentId)
    const reply = pending && replyOf(pending.asked, prompt)
    const cwd = await $.session.cwd()
    try {
      if (asked.length === 0) {
        // Commands alone: Codex is not asked, and a question it asked still waits.
      } else if (pending?.server.isEnded() || (!pending && expiredAnswer(lastAnswer(rows), prompt))) {
        held.delete(agentId)
        question = EXPIRED
      } else if (pending && !reply) {
        // Not an answer: ask again, Codex still waiting.
        question = `That does not answer Codex.\n\n${questionOf(pending.asked)}`
      } else if (pending && reply) {
        held.delete(agentId)
        server = pending.server
        run.threadId = pending.threadId
        await server.respond(pending.asked.id, reply)
        isTaken = true
        yield show(`answered Codex\n`)
        await note($, agentId, 'answered Codex')
      } else {
        // Once Codex has taken a message the agent's session goes on, even
        // where the conversation keeps no session line (a step stopped first).
        const sessionId = given.length > 0 ? (request.sessionId ?? (await read($, runs))[agentId]?.threadId) : undefined
        const first = sessionId === undefined
        // The spawn prompt's flags hold for every run of the agent; they are
        // not part of the task.
        const flags = flagsOf(request.opening, type.pin)
        if ('error' in flags) throw new Error(flags.error)
        const set = threadParamsOf((await read($, options))[agentId] ?? {})
        server = await open({ spawn: r => $.process.spawn(r), write: (p, t) => $.fs.write(p, t), stat: p => $.fs.stat(p) }, flags.args, cwd)
        const where = flags.cwd ?? cwd
        const config = { ...set.config, ...(await rootsOf(server, flags.addDirs)) }
        const overrides = { ...set, ...(Object.keys(config).length > 0 ? { config } : {}) }
        const thread = first
          ? await server.call('thread/start', { cwd: where, ...(flags.ephemeral ? { ephemeral: true } : {}), ...overrides })
          : await server.call('thread/resume', { threadId: sessionId, cwd: where, ...overrides })
        // What the session runs on, as Codex reports it.
        report = reportOf(thread)
        run.threadId = report.threadId
        // Known now, for /codex-status while the turn runs.
        await record($, agentId, report)
        model = report.model
        yield show(`codex ${labelOf({}, { model: report.model, effort: report.effort ?? undefined })} · ${type.shown}\ncodex session ${run.threadId}\n\n`)
        const images = flags.images.map(path => ({ type: 'localImage', path }))
        const schema = flags.outputSchema ? { outputSchema: JSON.parse(await $.fs.read(flags.outputSchema)) } : {}
        const opens = asked[0] === request.opening
        const text = opens ? (flagsOf(prompt, type.pin) as Flags).prompt : prompt
        const started = await server.call('turn/start', { threadId: run.threadId, input: [{ type: 'text', text }, ...images], ...schema })
        isTaken = true
        if (started?.turn?.id) working.set(agentId, { server, threadId: run.threadId!, turnId: started.turn.id })
      }
      while (server && !question) {
        const message = await unlessAborted(next.signal, server.next())
        if (!message) {
          if (!next.signal.aborted) run.error = `codex app-server exited: ${server.stderr().trim().split('\n').at(-1) || 'no reason given'}`
          break
        }
        if (message.id !== undefined) {
          const asked = { id: message.id, method: message.method, params: message.params }
          question = questionOf(asked)
          if (question) held.set(agentId, { server, asked, threadId: run.threadId! })
          else await server.respond(message.id, replyOf(asked, '')!)
          continue
        }
        const step = apply(run, message.method, message.params)
        if (step !== undefined) {
          yield show(step)
          await note($, agentId, step)
        }
        if (run.isDone) break
      }
    } catch (err) {
      run.error = (err as Error).message
      // Only a missing CLI, or one too old for app-server, earns the hint.
      if (`${run.error}\n${server?.stderr() ?? ''}`.includes(NO_CODEX) || /unrecognized subcommand '?app-server/.test(`${run.error}\n${server?.stderr() ?? ''}`)) {
        run.error += '. The codex mod needs the Codex CLI with `codex app-server` (0.159 or newer): `npm install -g @openai/codex`, then `codex login`.'
      }
    } finally {
      working.delete(agentId)
      if (server && !held.has(agentId)) server.close()
      // A step cut off (interrupted, or closed) before Codex took its messages,
      // asked or failed has passed nothing on: the next step sends them again.
      const isCutOff = asked.length > 0 && !isTaken && !question && !run.error
      if (!isCutOff) await update($, sent, all => ({ ...all, [agentId]: [...(all[agentId] ?? []), ...request.texts] }))
      // What Codex reported this session runs with, and its token total.
      await record($, agentId, report, run.tokens)
    }
  }

  // Codex's own token counts, so the agent's row shows what the run cost.
  const usage: TurnUsage | null = run.usage ? { ...run.usage, model } : null
  const codexSaid = question || (asked.length > 0 ? answerOf(run) : undefined)
  // A report that never reached the caller goes ahead of this step's answer;
  // with nothing new (the engine ran the loop again) the loop says only that.
  // A stopped step says only that it stopped, which is never such a report.
  const undelivered = undeliveredReport(rows)
  const message =
    codexSaid === STOPPED
      ? STOPPED
      : request
        ? [...(undelivered ? [undelivered] : []), ...replies, ...(codexSaid ? [codexSaid] : [])].join('\n\n')
        : (undelivered ?? 'codex: nothing new to send to Codex.')
  if (!handback) {
    // The session line lets a follow-up resume this run (see requestOf).
    const text = run.threadId ? `${message}\n\ncodex session ${run.threadId}` : message
    yield { kind: 'text', index: 1, text }
    yield { kind: 'stop', stopReason: 'end_turn', usage }
    return { turnId: e.turnId, index: e.index, answer: text, toolUses: [], stopReason: 'end_turn', usage }
  }
  if (progress === '' && !question) yield show(run.error ? `codex: ${run.error}\n` : 'codex: nothing to run.\n')
  const input = { message }
  yield { kind: 'tool', index: 1, id: `toolu_codex_${crypto.randomUUID().replaceAll('-', '')}`, name: HANDBACK }
  yield { kind: 'input', index: 1, json: JSON.stringify(input) }
  yield { kind: 'stop', stopReason: 'tool_use', usage }
  return { turnId: e.turnId, index: e.index, answer: progress, toolUses: [{ name: HANDBACK, input }], stopReason: 'tool_use', usage }
}

// `add-dir`: the config's writable roots plus the ones asked for, since a
// thread's setting replaces the config's list rather than adding to it.
async function rootsOf(server: Server, dirs: readonly string[]): Promise<Record<string, unknown>> {
  if (dirs.length === 0) return {}
  const { config } = await server.call('config/read', {})
  return { 'sandbox_workspace_write.writable_roots': [...(config?.sandbox_workspace_write?.writable_roots ?? []), ...dirs] }
}

files.hooks/view.ts:
// The codex agent whose view is open, if any, and the reply to the last
// /codex- command run in each such view. The band above the prompt sees the
// view (a render hook may not write $.state, so it is kept here) and draws the
// reply; a command reads the view. Display only: a reload drops both, and
// the next draw sets the view again.

let open: string | undefined
const replies = new Map<string, string>()

export function openView(): string | undefined {
  return open
}

// Says whether the open view changed; leaving a view drops its reply.
export function setOpenView(agentId: string | undefined): boolean {
  if (agentId === open) return false
  if (open !== undefined) replies.delete(open)
  open = agentId
  return true
}

export function replyIn(agentId: string): string | undefined {
  return replies.get(agentId)
}

export function setReply(agentId: string, reply: string): void {
  replies.set(agentId, reply)
}

files.hooks/names.ts:
// Codex model ids as people say them: `gpt-6.1-sol` reads `Sol 6.1`. An id
// of another shape is shown as it is.
export function nameOf(id: string): string {
  const match = /^gpt-([\d.]+)-([a-z]+)$/i.exec(id)
  if (!match) return id
  const name = match[2]!
  return `${name[0]!.toUpperCase()}${name.slice(1)} ${match[1]}`
}

